//! C ABI for hetero-kv (opaque handles; header: `include/hetero_kv.h`, generated by cbindgen).
//!
//! Conventions:
//! * Every fallible function returns `hkv_status`; constructors return NULL on failure. The
//!   message of the last failure on the calling thread is `hkv_last_error()`.
//! * `*_free` accepts NULL. Handles are not thread-affine; a session may be used from several
//!   threads (its operations serialize internally).
//! * Strings are NUL-terminated UTF-8. Panics never cross the boundary (`HKV_PANIC`).
//!
//! Covered: regions at device locations, specs, buffers, agents (registration, handshake
//! metadata, descriptor export/import as bytes, resolution), sessions with Selection-based
//! transfers and declared conversions, layer progress. Not yet: KV events and C-implemented
//! engines (NIXL plugin, P3).

#![allow(non_camel_case_types, clippy::missing_safety_doc)]

use std::cell::RefCell;
use std::collections::VecDeque;
use std::ffi::{c_char, c_void, CStr, CString};
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::sync::{Arc, Mutex};

use hetero_kv::engine::{CopyEngine, Direction, HostEngine, Representation, Route};
use hetero_kv::kv::{
    Geometry, KvBuffer, KvKind, KvSpec, LayerProgress, Layout, Selection, Split, Strides,
};
use std::collections::BTreeMap;

use hetero_kv::kv::{BlockHash, KvBufferRef, KvDescriptor};
use hetero_kv::memory::{Location, MemoryKind, Region};
use hetero_kv::session::Agent;
use hetero_kv::session::{Session, SessionState, TransferId};
use hetero_kv::Error;

/// Status codes. `HKV_OK` is 0; the error codes mirror the Rust error kinds.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum hkv_status {
    HKV_OK = 0,
    /// Malformed argument; nothing was submitted.
    HKV_INVALID = 1,
    /// No route/capability; nothing was submitted, no fallback.
    HKV_UNSUPPORTED = 2,
    /// Wrong lifecycle step or stale request; nothing changed.
    HKV_STATE = 3,
    /// Held by another request, or memory still referenced.
    HKV_BUSY = 4,
    /// Cancellation completed after fencing.
    HKV_CANCELLED = 5,
    /// Session poisoned; call `hkv_session_recover`.
    HKV_POISONED = 6,
    /// Engine failure or unverifiable completion; buffers uncertain, session poisoned.
    HKV_TRANSFER = 7,
    /// A required pointer argument was NULL or a string was not UTF-8.
    HKV_NULL = 8,
    /// Internal panic (a bug); state of the touched object is unspecified.
    HKV_PANIC = 9,
}

/// Memory tiers (see `hetero_kv::memory::MemoryKind`).
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub enum hkv_memory_kind {
    HKV_MEM_HOST = 0,
    HKV_MEM_HOST_PINNED = 1,
    HKV_MEM_CUDA = 2,
    HKV_MEM_RNGD = 3,
    HKV_MEM_ATOM = 4,
    HKV_MEM_STORAGE = 5,
    HKV_MEM_REMOTE = 6,
}

/// Where memory lives: kind, device index, and an optional node id (cross-host, later phases).
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct hkv_location {
    pub kind: hkv_memory_kind,
    pub index: u32,
    /// Non-zero if `node` is set; P0 routes accept local locations only.
    pub has_node: bool,
    pub node: u64,
}

/// KV element encodings.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub enum hkv_representation {
    HKV_BF16 = 0,
    HKV_FP16 = 1,
    HKV_DLFLOAT16 = 2,
    HKV_FP32 = 3,
}

/// Named layouts (see `hetero_kv::kv::Layout`).
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub enum hkv_layout_kind {
    /// One region per layer: [kv, block, token, head, dim].
    HKV_LAYOUT_LAYER_SEPARATE = 0,
    /// One region: [block, layer, kv, token, head, dim].
    HKV_LAYOUT_BLOCK_MAJOR = 1,
    /// One region: [layer, kv, block, token, head, dim].
    HKV_LAYOUT_LAYER_MAJOR = 2,
    /// One region per (layer, kv): [block, head, token, dim].
    HKV_LAYOUT_BHSD = 3,
}

/// Region split for explicitly strided layouts.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub enum hkv_split {
    HKV_SPLIT_NONE = 0,
    HKV_SPLIT_LAYER = 1,
    HKV_SPLIT_LAYER_KV = 2,
}

/// Session lifecycle states.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum hkv_session_state {
    HKV_SESSION_IDLE = 0,
    HKV_SESSION_RESERVED = 1,
    HKV_SESSION_TRANSFERRING = 2,
    HKV_SESSION_FENCED = 3,
    HKV_SESSION_ADMITTED = 4,
    HKV_SESSION_POISONED = 5,
}

/// Logical KV geometry.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct hkv_geometry {
    pub representation: hkv_representation,
    /// 0: separate K and V planes; 1: one MLA latent plane.
    pub latent: u32,
    pub layers: u32,
    pub blocks: u32,
    pub block_size: u32,
    pub heads: u32,
    pub head_dim: u32,
}

/// In-region byte strides (split axes must be 0).
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct hkv_strides {
    pub layer: u64,
    pub kv: u64,
    pub block: u64,
    pub token: u64,
    pub head: u64,
}

/// What to copy: layers `[layer_start, layer_end)` and `tokens` tokens through block tables
/// (`tokens == 0` means the rest of the source table).
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct hkv_selection {
    pub layer_start: u32,
    pub layer_end: u32,
    pub src_blocks: *const u32,
    pub n_src_blocks: usize,
    pub dst_blocks: *const u32,
    pub n_dst_blocks: usize,
    pub src_start: u64,
    pub dst_start: u64,
    pub tokens: u64,
}

/// Fence receipt.
#[repr(C)]
#[derive(Debug, Clone, Copy, Default)]
pub struct hkv_receipt {
    pub transfers: u32,
    pub spans: u64,
    pub bytes: u64,
}

/// One layer-progress span.
#[repr(C)]
#[derive(Debug, Clone, Copy, Default)]
pub struct hkv_progress_span {
    pub layer_start: i64,
    pub layer_end: i64,
    pub token_start: i64,
    pub token_end: i64,
}

/// Copy engine handle.
pub struct hkv_engine(Arc<dyn CopyEngine>);
/// Owned region handle.
pub struct hkv_region(Region);
/// KV spec handle.
pub struct hkv_spec(KvSpec);
/// KV buffer handle: an owned buffer (owns its regions) or a reference resolved from a
/// descriptor (cannot be reclaimed).
pub enum hkv_buffer {
    Owned(KvBuffer),
    Ref(KvBufferRef),
}

impl hkv_buffer {
    fn share(&self) -> KvBufferRef {
        match self {
            hkv_buffer::Owned(b) => b.share(),
            hkv_buffer::Ref(r) => r.clone(),
        }
    }
}

/// Agent handle: identity, registration and descriptors.
pub struct hkv_agent(Agent);
/// Serializable KV buffer descriptor.
pub struct hkv_descriptor(KvDescriptor);
/// Session handle.
pub struct hkv_session(Session);
/// Layer-progress handle.
pub struct hkv_progress {
    inner: LayerProgress,
    drained: Mutex<VecDeque<(i64, i64, i64, i64)>>,
}

thread_local! {
    static LAST_ERROR: RefCell<CString> = RefCell::new(CString::default());
}

fn set_error(msg: &str) {
    let c = CString::new(msg.replace('\0', " ")).unwrap_or_default();
    LAST_ERROR.with(|e| *e.borrow_mut() = c);
}

fn status_of(e: &Error) -> hkv_status {
    match e {
        Error::Invalid(_) => hkv_status::HKV_INVALID,
        Error::Unsupported(_) => hkv_status::HKV_UNSUPPORTED,
        Error::State(_) => hkv_status::HKV_STATE,
        Error::Busy(_) => hkv_status::HKV_BUSY,
        Error::Cancelled(_) => hkv_status::HKV_CANCELLED,
        Error::Poisoned(_) => hkv_status::HKV_POISONED,
        Error::Transfer(_) => hkv_status::HKV_TRANSFER,
    }
}

enum Fail {
    Lib(Error),
    Null,
}

impl From<Error> for Fail {
    fn from(e: Error) -> Self {
        Fail::Lib(e)
    }
}

type R<T> = Result<T, Fail>;

/// Run `f`, converting errors and panics into a status and the thread's last error.
fn guard(f: impl FnOnce() -> R<()>) -> hkv_status {
    match catch_unwind(AssertUnwindSafe(f)) {
        Ok(Ok(())) => hkv_status::HKV_OK,
        Ok(Err(Fail::Lib(e))) => {
            set_error(&e.to_string());
            status_of(&e)
        }
        Ok(Err(Fail::Null)) => {
            set_error("NULL argument or invalid UTF-8 string");
            hkv_status::HKV_NULL
        }
        Err(_) => {
            set_error("internal panic");
            hkv_status::HKV_PANIC
        }
    }
}

/// Like [`guard`] for constructors: a boxed handle or NULL.
fn construct<T>(f: impl FnOnce() -> R<T>) -> *mut T {
    let mut out = None;
    guard(|| {
        out = Some(f()?);
        Ok(())
    });
    out.map_or(std::ptr::null_mut(), |v| Box::into_raw(Box::new(v)))
}

unsafe fn str_arg<'a>(p: *const c_char) -> R<&'a str> {
    if p.is_null() {
        return Err(Fail::Null);
    }
    CStr::from_ptr(p).to_str().map_err(|_| Fail::Null)
}

unsafe fn ref_arg<'a, T>(p: *const T) -> R<&'a T> {
    p.as_ref().ok_or(Fail::Null)
}

unsafe fn slice_arg<'a, T>(p: *const T, n: usize) -> R<&'a [T]> {
    if n == 0 {
        return Ok(&[]);
    }
    if p.is_null() {
        return Err(Fail::Null);
    }
    Ok(std::slice::from_raw_parts(p, n))
}

fn location(l: &hkv_location) -> Location {
    let loc = Location::new(MemoryKind::ALL[l.kind as usize], l.index);
    if l.has_node {
        loc.on_node(l.node)
    } else {
        loc
    }
}

fn repr(r: hkv_representation) -> Representation {
    Representation::ALL[r as usize]
}

fn geometry(g: &hkv_geometry) -> R<Geometry> {
    let kv = match g.latent {
        0 => KvKind::KeyValue,
        1 => KvKind::Latent,
        _ => return Err(Error::Invalid("latent must be 0 or 1".into()).into()),
    };
    Ok(Geometry {
        representation: repr(g.representation),
        kv,
        layers: g.layers,
        blocks: g.blocks,
        block_size: g.block_size,
        heads: g.heads,
        head_dim: g.head_dim,
    })
}

// --- library -----------------------------------------------------------------------------

/// Library version (static string).
#[no_mangle]
pub extern "C" fn hkv_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}

/// Message of the last failure on this thread (valid until the next failing call on it).
#[no_mangle]
pub extern "C" fn hkv_last_error() -> *const c_char {
    LAST_ERROR.with(|e| e.borrow().as_ptr())
}

// --- L2 engines ----------------------------------------------------------------------------

/// The host reference engine.
#[no_mangle]
pub extern "C" fn hkv_host_engine_new() -> *mut hkv_engine {
    construct(|| Ok(hkv_engine(Arc::new(HostEngine::new()))))
}

/// Free an engine (sessions keep their own reference).
#[no_mangle]
pub unsafe extern "C" fn hkv_engine_free(engine: *mut hkv_engine) {
    if !engine.is_null() {
        drop(Box::from_raw(engine));
    }
}

// --- L1 regions ----------------------------------------------------------------------------

/// Allocate `len` zeroed, page-aligned host bytes.
#[no_mangle]
pub extern "C" fn hkv_region_host_new(len: usize) -> *mut hkv_region {
    construct(|| Ok(hkv_region(Region::host(len)?)))
}

/// Wrap caller-owned memory at `location`. The memory must stay valid until the region handle is
/// freed, and must not be touched while the region is inside a buffer.
#[no_mangle]
pub unsafe extern "C" fn hkv_region_wrap(
    location: hkv_location,
    addr: *mut c_void,
    len: usize,
) -> *mut hkv_region {
    construct(|| {
        Ok(hkv_region(Region::external(
            self::location(&location),
            addr as usize,
            len,
            None,
        )?))
    })
}

/// Host bytes of an owned region (NULL for device kinds).
#[no_mangle]
pub unsafe extern "C" fn hkv_region_data(region: *mut hkv_region) -> *mut u8 {
    region
        .as_mut()
        .and_then(|r| r.0.as_mut_slice())
        .map_or(std::ptr::null_mut(), |s| s.as_mut_ptr())
}

/// Length in bytes (0 for NULL).
#[no_mangle]
pub unsafe extern "C" fn hkv_region_len(region: *const hkv_region) -> usize {
    region.as_ref().map_or(0, |r| r.0.len())
}

/// Free a region.
#[no_mangle]
pub unsafe extern "C" fn hkv_region_free(region: *mut hkv_region) {
    if !region.is_null() {
        drop(Box::from_raw(region));
    }
}

// --- L3 specs, buffers, progress -----------------------------------------------------------

/// Spec with a named layout.
#[no_mangle]
pub unsafe extern "C" fn hkv_spec_new(
    model_id: *const c_char,
    revision: *const c_char,
    layout: hkv_layout_kind,
    geometry: *const hkv_geometry,
) -> *mut hkv_spec {
    construct(|| {
        let g = self::geometry(ref_arg(geometry)?)?;
        let layout = match layout {
            hkv_layout_kind::HKV_LAYOUT_LAYER_SEPARATE => Layout::layer_separate(g),
            hkv_layout_kind::HKV_LAYOUT_BLOCK_MAJOR => Layout::block_major(g),
            hkv_layout_kind::HKV_LAYOUT_LAYER_MAJOR => Layout::layer_major(g),
            hkv_layout_kind::HKV_LAYOUT_BHSD => Layout::bhsd(g),
        }?;
        Ok(hkv_spec(KvSpec::new(
            str_arg(model_id)?,
            str_arg(revision)?,
            layout,
        )?))
    })
}

/// Spec with explicit strides.
#[no_mangle]
pub unsafe extern "C" fn hkv_spec_new_strided(
    model_id: *const c_char,
    revision: *const c_char,
    geometry: *const hkv_geometry,
    split: hkv_split,
    strides: *const hkv_strides,
    region_bytes: u64,
) -> *mut hkv_spec {
    construct(|| {
        let g = self::geometry(ref_arg(geometry)?)?;
        let s = ref_arg(strides)?;
        let split = match split {
            hkv_split::HKV_SPLIT_NONE => Split::None,
            hkv_split::HKV_SPLIT_LAYER => Split::Layer,
            hkv_split::HKV_SPLIT_LAYER_KV => Split::LayerKv,
        };
        let strides = Strides {
            layer: s.layer,
            kv: s.kv,
            block: s.block,
            token: s.token,
            head: s.head,
        };
        let layout = Layout::strided(g, split, strides, region_bytes)?;
        Ok(hkv_spec(KvSpec::new(
            str_arg(model_id)?,
            str_arg(revision)?,
            layout,
        )?))
    })
}

/// Regions a buffer of this spec needs (0 for NULL).
#[no_mangle]
pub unsafe extern "C" fn hkv_spec_region_count(spec: *const hkv_spec) -> usize {
    spec.as_ref().map_or(0, |s| s.0.layout.region_count())
}

/// Minimum bytes per region (0 for NULL).
#[no_mangle]
pub unsafe extern "C" fn hkv_spec_region_bytes(spec: *const hkv_spec) -> u64 {
    spec.as_ref().map_or(0, |s| s.0.layout.region_bytes())
}

/// Free a spec.
#[no_mangle]
pub unsafe extern "C" fn hkv_spec_free(spec: *mut hkv_spec) {
    if !spec.is_null() {
        drop(Box::from_raw(spec));
    }
}

/// Build a buffer. On success the region handles are consumed and the array entries set to
/// NULL; on failure they are untouched.
#[no_mangle]
pub unsafe extern "C" fn hkv_buffer_new(
    spec: *const hkv_spec,
    regions: *mut *mut hkv_region,
    n: usize,
) -> *mut hkv_buffer {
    construct(|| {
        let spec = &ref_arg(spec)?.0;
        let ptrs = slice_arg(regions as *const *mut hkv_region, n)?;
        if ptrs.iter().any(|p| p.is_null()) {
            return Err(Fail::Null);
        }
        // Validate on borrowed regions first so a failure consumes nothing.
        let borrowed: Vec<&Region> = ptrs.iter().map(|&p| &(*p).0).collect();
        if n != spec.layout.region_count()
            || borrowed.iter().any(|r| {
                (r.len() as u64) < spec.layout.region_bytes() || r.kind() != borrowed[0].kind()
            })
        {
            return Err(Error::Invalid("regions do not fit the spec's layout".into()).into());
        }
        let owned: Vec<Region> = (0..n)
            .map(|i| {
                let p = *regions.add(i);
                *regions.add(i) = std::ptr::null_mut();
                Box::from_raw(p).0
            })
            .collect();
        Ok(hkv_buffer::Owned(KvBuffer::new(spec.clone(), owned)?))
    })
}

/// Take the regions back into `out[0..n]` and free the buffer. Fails (buffer unchanged) while
/// a session, transfer or registration still references it, and with `HKV_STATE` for a
/// resolved (reference) buffer.
#[no_mangle]
pub unsafe extern "C" fn hkv_buffer_reclaim(
    buffer: *mut hkv_buffer,
    out: *mut *mut hkv_region,
    n: usize,
) -> hkv_status {
    guard(|| {
        if buffer.is_null() || out.is_null() {
            return Err(Fail::Null);
        }
        match &*buffer {
            hkv_buffer::Ref(_) => {
                return Err(Error::State(
                    "a resolved buffer reference has no regions to reclaim".into(),
                )
                .into())
            }
            hkv_buffer::Owned(b) if b.regions().len() != n => {
                return Err(
                    Error::Invalid("output array length differs from region count".into()).into(),
                )
            }
            hkv_buffer::Owned(_) => {}
        }
        let hkv_buffer::Owned(buf) = *Box::from_raw(buffer) else {
            unreachable!("checked above")
        };
        match buf.reclaim() {
            Ok(regions) => {
                for (i, r) in regions.into_iter().enumerate() {
                    *out.add(i) = Box::into_raw(Box::new(hkv_region(r)));
                }
                Ok(())
            }
            Err(fail) => {
                let (b, e) = (fail.buffer, fail.error);
                // Put the buffer back at the caller's address.
                std::ptr::write(buffer, hkv_buffer::Owned(b));
                Err(e.into())
            }
        }
    })
}

/// Free a buffer. Region memory is released once no session references it (memory left
/// uncertain by a failed transfer is never released).
#[no_mangle]
pub unsafe extern "C" fn hkv_buffer_free(buffer: *mut hkv_buffer) {
    if !buffer.is_null() {
        drop(Box::from_raw(buffer));
    }
}

/// Layer-progress tracker for `layers` layers over tokens `[start, end)`.
#[no_mangle]
pub extern "C" fn hkv_progress_new(layers: i64, start: i64, end: i64) -> *mut hkv_progress {
    construct(|| {
        Ok(hkv_progress {
            inner: LayerProgress::new(layers, start, end)?,
            drained: Mutex::new(VecDeque::new()),
        })
    })
}

/// Publish a span.
#[no_mangle]
pub unsafe extern "C" fn hkv_progress_publish(
    progress: *const hkv_progress,
    layer_start: i64,
    layer_end: i64,
    token_start: i64,
    token_end: i64,
) -> hkv_status {
    guard(|| {
        Ok(ref_arg(progress)?
            .inner
            .publish((layer_start, layer_end, token_start, token_end))?)
    })
}

/// Drain up to `cap` spans into `out`; `*n` receives the count. Remaining spans stay queued.
#[no_mangle]
pub unsafe extern "C" fn hkv_progress_drain(
    progress: *const hkv_progress,
    out: *mut hkv_progress_span,
    cap: usize,
    n: *mut usize,
) -> hkv_status {
    guard(|| {
        let p = ref_arg(progress)?;
        if n.is_null() || (cap > 0 && out.is_null()) {
            return Err(Fail::Null);
        }
        let mut q = p.drained.lock().unwrap_or_else(|e| e.into_inner());
        q.extend(p.inner.drain());
        let count = cap.min(q.len());
        for i in 0..count {
            let (a, b, c, d) = q.pop_front().unwrap_or_default();
            *out.add(i) = hkv_progress_span {
                layer_start: a,
                layer_end: b,
                token_start: c,
                token_end: d,
            };
        }
        *n = count;
        Ok(())
    })
}

/// True if spans are waiting to be drained.
#[no_mangle]
pub unsafe extern "C" fn hkv_progress_pending(progress: *const hkv_progress) -> bool {
    progress.as_ref().is_some_and(|p| {
        p.inner.pending()
            || !p
                .drained
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .is_empty()
    })
}

/// Close once every layer covers the reservation.
#[no_mangle]
pub unsafe extern "C" fn hkv_progress_finish(progress: *const hkv_progress) -> hkv_status {
    guard(|| Ok(ref_arg(progress)?.inner.finish()?))
}

/// Free a tracker.
#[no_mangle]
pub unsafe extern "C" fn hkv_progress_free(progress: *mut hkv_progress) {
    if !progress.is_null() {
        drop(Box::from_raw(progress));
    }
}

// --- L4 agents and descriptors --------------------------------------------------------------

/// New agent (`endpoint` may be NULL).
#[no_mangle]
pub unsafe extern "C" fn hkv_agent_new(
    name: *const c_char,
    endpoint: *const c_char,
) -> *mut hkv_agent {
    construct(|| {
        let endpoint = if endpoint.is_null() {
            None
        } else {
            Some(str_arg(endpoint)?.to_owned())
        };
        Ok(hkv_agent(Agent::new(str_arg(name)?, endpoint)))
    })
}

/// Agent id (0 for NULL); descriptors exported by the agent carry it.
#[no_mangle]
pub unsafe extern "C" fn hkv_agent_id(agent: *const hkv_agent) -> u64 {
    agent.as_ref().map_or(0, |a| a.0.id())
}

/// Copy `bytes` into `out[0..cap]`; `*len` always receives the full size. `HKV_INVALID` if
/// `cap` is too small (call with `cap == 0` to size the buffer).
unsafe fn write_bytes(bytes: &[u8], out: *mut u8, cap: usize, len: *mut usize) -> R<()> {
    *len.as_mut().ok_or(Fail::Null)? = bytes.len();
    if cap < bytes.len() {
        return Err(Error::Invalid(format!("buffer of {cap} bytes, need {}", bytes.len())).into());
    }
    if !bytes.is_empty() {
        if out.is_null() {
            return Err(Fail::Null);
        }
        std::ptr::copy_nonoverlapping(bytes.as_ptr(), out, bytes.len());
    }
    Ok(())
}

/// Versioned handshake metadata bytes (see `write_bytes` conventions: `cap`, `*len`).
#[no_mangle]
pub unsafe extern "C" fn hkv_agent_meta(
    agent: *const hkv_agent,
    out: *mut u8,
    cap: usize,
    len: *mut usize,
) -> hkv_status {
    guard(|| write_bytes(&ref_arg(agent)?.0.meta().to_bytes(), out, cap, len))
}

/// Register `buffer` with the agent and describe it. `hash_blocks[i]` -> `hashes[i]` are optional
/// integer block hashes (`n_hashes` may be 0).
#[no_mangle]
pub unsafe extern "C" fn hkv_agent_export(
    agent: *const hkv_agent,
    buffer: *const hkv_buffer,
    hash_blocks: *const u32,
    hashes: *const u64,
    n_hashes: usize,
) -> *mut hkv_descriptor {
    construct(|| {
        let blocks = slice_arg(hash_blocks, n_hashes)?;
        let values = slice_arg(hashes, n_hashes)?;
        let map: BTreeMap<u32, BlockHash> = blocks
            .iter()
            .zip(values)
            .map(|(&b, &h)| (b, BlockHash::Int(h)))
            .collect();
        let buf = ref_arg(buffer)?.share();
        Ok(hkv_descriptor(ref_arg(agent)?.0.export(&buf, map)?))
    })
}

/// Drop the registrations of a descriptor this agent exported.
#[no_mangle]
pub unsafe extern "C" fn hkv_agent_release(
    agent: *const hkv_agent,
    descriptor: *const hkv_descriptor,
) -> hkv_status {
    guard(|| Ok(ref_arg(agent)?.0.release(&ref_arg(descriptor)?.0)?))
}

/// Free an agent (its registrations, and so the registered memory, are released).
#[no_mangle]
pub unsafe extern "C" fn hkv_agent_free(agent: *mut hkv_agent) {
    if !agent.is_null() {
        drop(Box::from_raw(agent));
    }
}

/// Versioned wire bytes of a descriptor (`cap`/`*len` as for `hkv_agent_meta`).
#[no_mangle]
pub unsafe extern "C" fn hkv_descriptor_to_bytes(
    descriptor: *const hkv_descriptor,
    out: *mut u8,
    cap: usize,
    len: *mut usize,
) -> hkv_status {
    guard(|| write_bytes(&ref_arg(descriptor)?.0.to_bytes(), out, cap, len))
}

/// Decode descriptor bytes (from any peer).
#[no_mangle]
pub unsafe extern "C" fn hkv_descriptor_from_bytes(
    data: *const u8,
    len: usize,
) -> *mut hkv_descriptor {
    construct(|| {
        Ok(hkv_descriptor(KvDescriptor::from_bytes(slice_arg(
            data, len,
        )?)?))
    })
}

/// Resolve a descriptor to a buffer reference usable in sessions (P0: agents in this process;
/// `HKV_UNSUPPORTED` otherwise). Free it with `hkv_buffer_free`.
#[no_mangle]
pub unsafe extern "C" fn hkv_descriptor_resolve(
    descriptor: *const hkv_descriptor,
) -> *mut hkv_buffer {
    construct(|| Ok(hkv_buffer::Ref(ref_arg(descriptor)?.0.resolve()?)))
}

/// Free a descriptor (does not deregister; see `hkv_agent_release`).
#[no_mangle]
pub unsafe extern "C" fn hkv_descriptor_free(descriptor: *mut hkv_descriptor) {
    if !descriptor.is_null() {
        drop(Box::from_raw(descriptor));
    }
}

// --- L4 sessions ---------------------------------------------------------------------------

/// Session over an explicitly selected route `src -> dst`, converting `src_repr` to `dst_repr`
/// (pass the same value twice for a plain copy); NULL (`HKV_UNSUPPORTED`) if the engine did not
/// declare that route. Sessions are cheap: share one engine handle and create one session per
/// request; any number may run concurrently from different threads.
#[no_mangle]
pub unsafe extern "C" fn hkv_session_new(
    engine: *const hkv_engine,
    src: hkv_location,
    dst: hkv_location,
    src_repr: hkv_representation,
    dst_repr: hkv_representation,
) -> *mut hkv_session {
    construct(|| {
        let engine = ref_arg(engine)?.0.clone();
        let route = Route::select_converting(
            engine,
            location(&src),
            location(&dst),
            repr(src_repr),
            repr(dst_repr),
        )?;
        Ok(hkv_session(Session::new(route)))
    })
}

/// Free a session. A poisoned session's retained buffers stay pinned (and uncertain memory is
/// never released).
#[no_mangle]
pub unsafe extern "C" fn hkv_session_free(session: *mut hkv_session) {
    if !session.is_null() {
        drop(Box::from_raw(session));
    }
}

/// Current state.
#[no_mangle]
pub unsafe extern "C" fn hkv_session_get_state(session: *const hkv_session) -> hkv_session_state {
    use hkv_session_state::*;
    match session.as_ref().map(|s| s.0.state()) {
        Some(SessionState::Idle) | None => HKV_SESSION_IDLE,
        Some(SessionState::Reserved) => HKV_SESSION_RESERVED,
        Some(SessionState::Transferring) => HKV_SESSION_TRANSFERRING,
        Some(SessionState::Fenced) => HKV_SESSION_FENCED,
        Some(SessionState::Admitted) => HKV_SESSION_ADMITTED,
        Some(SessionState::Poisoned) => HKV_SESSION_POISONED,
    }
}

/// Reserve `n` destination buffers (one per KV group).
#[no_mangle]
pub unsafe extern "C" fn hkv_session_reserve(
    session: *const hkv_session,
    request_id: *const c_char,
    dst: *const *const hkv_buffer,
    n: usize,
) -> hkv_status {
    guard(|| {
        let s = ref_arg(session)?;
        let bufs = slice_arg(dst, n)?
            .iter()
            .map(|&b| ref_arg(b).map(|b| b.share()))
            .collect::<R<Vec<_>>>()?;
        Ok(s.0.reserve(str_arg(request_id)?, bufs)?)
    })
}

/// Submit `n` selections from `src` into destination group `group` as one job.
/// `direction`: 0 = write (push), 1 = read (pull).
#[no_mangle]
pub unsafe extern "C" fn hkv_session_transfer(
    session: *const hkv_session,
    request_id: *const c_char,
    group: usize,
    src: *const hkv_buffer,
    selections: *const hkv_selection,
    n: usize,
    direction: u32,
    transfer_id: *mut u64,
) -> hkv_status {
    guard(|| {
        let s = ref_arg(session)?;
        let src = ref_arg(src)?.share();
        let sels = slice_arg(selections, n)?
            .iter()
            .map(|c| {
                Ok(Selection {
                    layers: c.layer_start..c.layer_end,
                    src_blocks: slice_arg(c.src_blocks, c.n_src_blocks)?.to_vec(),
                    dst_blocks: slice_arg(c.dst_blocks, c.n_dst_blocks)?.to_vec(),
                    src_start: c.src_start,
                    dst_start: c.dst_start,
                    tokens: (c.tokens != 0).then_some(c.tokens),
                })
            })
            .collect::<R<Vec<_>>>()?;
        let direction = match direction {
            0 => Direction::Write,
            1 => Direction::Read,
            _ => {
                return Err(Error::Invalid("direction must be 0 (write) or 1 (read)".into()).into())
            }
        };
        let id =
            s.0.transfer(str_arg(request_id)?, group, &src, &sels, direction)?;
        if let Some(out) = transfer_id.as_mut() {
            *out = id.0;
        }
        Ok(())
    })
}

/// Non-blocking completion check of one transfer.
#[no_mangle]
pub unsafe extern "C" fn hkv_session_poll(
    session: *const hkv_session,
    request_id: *const c_char,
    transfer_id: u64,
    done: *mut bool,
) -> hkv_status {
    guard(|| {
        let d = ref_arg(session)?
            .0
            .poll(str_arg(request_id)?, TransferId(transfer_id))?;
        *done.as_mut().ok_or(Fail::Null)? = d;
        Ok(())
    })
}

/// Wait for one transfer.
#[no_mangle]
pub unsafe extern "C" fn hkv_session_wait(
    session: *const hkv_session,
    request_id: *const c_char,
    transfer_id: u64,
) -> hkv_status {
    guard(|| {
        Ok(ref_arg(session)?
            .0
            .wait(str_arg(request_id)?, TransferId(transfer_id))?)
    })
}

/// Wait for every transfer touching `layer`.
#[no_mangle]
pub unsafe extern "C" fn hkv_session_wait_layer(
    session: *const hkv_session,
    request_id: *const c_char,
    layer: u32,
) -> hkv_status {
    guard(|| {
        Ok(ref_arg(session)?
            .0
            .wait_layer(str_arg(request_id)?, layer)?)
    })
}

/// Wait for and verify every transfer; fills `receipt` if non-NULL.
#[no_mangle]
pub unsafe extern "C" fn hkv_session_fence(
    session: *const hkv_session,
    request_id: *const c_char,
    receipt: *mut hkv_receipt,
) -> hkv_status {
    guard(|| {
        let r = ref_arg(session)?.0.fence(str_arg(request_id)?)?;
        if let Some(out) = receipt.as_mut() {
            *out = hkv_receipt {
                transfers: r.transfers,
                spans: r.spans,
                bytes: r.bytes,
            };
        }
        Ok(())
    })
}

/// Admission hook: make the destination visible; return `HKV_OK` or any error status.
pub type hkv_notify_fn = Option<unsafe extern "C" fn(user: *mut c_void) -> hkv_status>;

/// Admit a fenced request, calling `notify(user)` first (NULL: no hook).
#[no_mangle]
pub unsafe extern "C" fn hkv_session_admit(
    session: *const hkv_session,
    request_id: *const c_char,
    notify: hkv_notify_fn,
    user: *mut c_void,
) -> hkv_status {
    guard(|| {
        let hook = || match notify {
            None => Ok(()),
            Some(f) => match f(user) {
                hkv_status::HKV_OK => Ok(()),
                s => Err(Error::Transfer(format!(
                    "admission hook returned status {}",
                    s as i32
                ))),
            },
        };
        ref_arg(session)?.0.admit(str_arg(request_id)?, hook)?;
        Ok(())
    })
}

/// Finish an admitted request; `passed = false` poisons the session.
#[no_mangle]
pub unsafe extern "C" fn hkv_session_finish(
    session: *const hkv_session,
    request_id: *const c_char,
    passed: bool,
) -> hkv_status {
    guard(|| Ok(ref_arg(session)?.0.finish(str_arg(request_id)?, passed)?))
}

/// Cancel a request (cooperative; never aborts device work).
#[no_mangle]
pub unsafe extern "C" fn hkv_session_cancel(
    session: *const hkv_session,
    request_id: *const c_char,
) -> hkv_status {
    guard(|| Ok(ref_arg(session)?.0.cancel(str_arg(request_id)?)?))
}

/// Quiesce the engine and return a poisoned session to idle.
#[no_mangle]
pub unsafe extern "C" fn hkv_session_recover(session: *const hkv_session) -> hkv_status {
    guard(|| Ok(ref_arg(session)?.0.recover()?))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn status_mapping_and_null_handling() {
        unsafe {
            assert_eq!(hkv_session_recover(std::ptr::null()), hkv_status::HKV_NULL);
            assert!(!CStr::from_ptr(hkv_last_error()).to_bytes().is_empty());
            assert!(hkv_region_host_new(0).is_null());
            let at = |kind| hkv_location {
                kind,
                index: 0,
                has_node: false,
                node: 0,
            };
            let bf16 = hkv_representation::HKV_BF16;
            let host = at(hkv_memory_kind::HKV_MEM_HOST);
            assert!(hkv_session_new(std::ptr::null(), host, host, bf16, bf16).is_null());
            let e = hkv_host_engine_new();
            let s = hkv_session_new(e, host, at(hkv_memory_kind::HKV_MEM_CUDA), bf16, bf16);
            assert!(s.is_null());
            assert!(CStr::from_ptr(hkv_last_error())
                .to_str()
                .unwrap()
                .contains("no route"));
            hkv_engine_free(e);
        }
    }
}
